                                                                                                                                                                                                                                          pg_get_functiondef                                                                                                                                                                                                                                          
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 CREATE OR REPLACE FUNCTION public.finance_sku_order_details_core_v3(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)                                                              +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 AS $function$\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 declare\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);\r                                                                                                                                                                                                                                                                                                                                                                                        +
   v_tenant_id uuid;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_role text;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_start date := coalesce(p_start, date_trunc('month', timezone('Asia/Jakarta', now()))::date);\r                                                                                                                                                                                                                                                                                                                                                                                                  +
   v_end date := coalesce(p_end, timezone('Asia/Jakarta', now())::date);\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_start_ts timestamptz;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_end_ts timestamptz;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_marketplace text;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_account_id uuid := p_account_id;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
   v_marketplace_sku text := lower(nullif(trim(coalesce(p_marketplace_sku, '')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_local_sku text := lower(nullif(trim(coalesce(p_local_sku, '')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_search text := lower(nullif(trim(coalesce(p_search, '')), ''));\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_filter text := lower(trim(coalesce(p_payout_filter, 'all')));\r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   v_page integer := greatest(coalesce(p_page, 1), 1);\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 25);\r                                                                                                                                                                                                                                                                                                                                                                                                                       +
   v_offset integer;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_detail_mode boolean;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 begin\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   perform set_config('work_mem', '64MB', true);\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     coalesce(\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
       case\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         when (v_claims->>'tenant_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'\r                                                                                                                                                                                                                                                                                                                                                                                         +
         then (v_claims->>'tenant_id')::uuid\r                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         else null::uuid\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       end,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       (select u.tenant_id from public.users u where u.user_id = auth.uid() limit 1)\r                                                                                                                                                                                                                                                                                                                                                                                                               +
     ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
     coalesce(nullif(v_claims->>'role', ''), '')\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   into v_tenant_id, v_role;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   v_start_ts := (v_start::timestamp at time zone 'Asia/Jakarta');\r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   v_end_ts := ((v_end + 1)::timestamp at time zone 'Asia/Jakarta');\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_offset := (v_page - 1) * v_page_size;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   v_filter := case\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     when v_filter in ('settled', 'released', 'release', 'payout', 'paid payout', 'sudah payout') then 'paid'\r                                                                                                                                                                                                                                                                                                                                                                                      +
     when v_filter in ('pending', 'belum payout', 'no payout', 'missing payout') then 'unpaid'\r                                                                                                                                                                                                                                                                                                                                                                                                     +
     when v_filter = '' then 'all'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
     else v_filter\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   end;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   v_marketplace := case\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'\r                                                                                                                                                                                                                                                                                                                                                                                  +
     when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'\r                                                                                                                                                                                                                                                                                                                                                                                  +
     else null\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   end;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   v_detail_mode := v_marketplace_sku is not null\r                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     or v_local_sku is not null\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     or v_search is not null;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   if v_role <> 'service_role' and v_tenant_id is null then\r                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     return jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
       'rows', '[]'::jsonb,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       'page', v_page,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
       'page_size', v_page_size,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       'total', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
       'total_count', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       'total_pages', 1,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       'source', 'finance_sku_order_details_fast_mtd'\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     );\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   if v_detail_mode and v_marketplace_sku = 'missing_or_adjustment' then\r                                                                                                                                                                                                                                                                                                                                                                                                                           +
     return (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       with finance_adjustments as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
         select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           tenant_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           marketplace_account_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(nullif(order_id, ''), 'ADJ-' || md5(random()::text)) as order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                             +
           gross_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           payout_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           net_settlement,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           settlement_date,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           period_start\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
         from public.marketplace_finance_reports fr\r                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         where tenant_id = v_tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           and (v_marketplace is null or lower(coalesce(marketplace, '')) like '%' || v_marketplace || '%')\r                                                                                                                                                                                                                                                                                                                                                                                        +
           and (v_account_id is null or marketplace_account_id = v_account_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
           and coalesce(settlement_date, period_start) >= v_start\r                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           and coalesce(settlement_date, period_start) <= v_end\r                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           and not exists (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             select 1 from public.marketplace_orders o\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             where o.tenant_id = fr.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
               and coalesce(nullif(o.external_order_id, ''), nullif(o.order_sn, ''), o.marketplace_order_id::text) = coalesce(nullif(fr.order_id, ''), fr.marketplace_order_id::text)\r                                                                                                                                                                                                                                                                                                              +
           )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         select *\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from finance_adjustments\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         order by coalesce(settlement_date, period_start) desc, order_key\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
         offset v_offset\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         limit v_page_size\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       select jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         'rows', coalesce(jsonb_agg(jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'source', 'finance_sku_order_details_fast_mtd_detail',\r                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_id', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_sn', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'marketplace_order_id', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'marketplace_order_item_id', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'resi', '-',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'tracking_number', '-',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'order_date', coalesce(settlement_date, period_start),\r                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_created_at', coalesce(settlement_date, period_start),\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'marketplace', marketplace,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'marketplace_account_id', marketplace_account_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'local_sku', 'Unmapped',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           'sku', 'missing_or_adjustment',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'marketplace_sku_id', 'missing_or_adjustment',\r                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'marketplace_sku', 'missing_or_adjustment',\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'marketplace_seller_sku', 'missing_or_adjustment',\r                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'product_name', 'Platform Adjustment / Missing Order',\r                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'variant_name', 'N/A',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'marketplace_variation_name', 'N/A',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           'qty', 1,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'quantity', 1,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'gross', coalesce(gross_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'gross_amount', coalesce(gross_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           'gross_total', coalesce(gross_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'gross_per_item', coalesce(gross_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout', coalesce(payout_amount, net_settlement, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'payout_amount', coalesce(payout_amount, net_settlement, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout_per_item', coalesce(payout_amount, net_settlement, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'hpp', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'hpp_total', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'hpp_per_item', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'unit_hpp', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           'hpp_status', 'HPP belum mapping',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'target_margin_percent', 0,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'finance_status', 'SETTLED',\r                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'payout_status', 'SETTLED'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         ) order by coalesce(settlement_date, period_start) desc, order_key), '[]'::jsonb),\r                                                                                                                                                                                                                                                                                                                                                                                                        +
         'page', v_page,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         'page_size', v_page_size,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         'total', (select count(*) from finance_adjustments),\r                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         'total_count', (select count(*) from finance_adjustments),\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
         'total_pages', greatest(1, ceil((select count(*) from finance_adjustments)::numeric / v_page_size)::integer),\r                                                                                                                                                                                                                                                                                                                                                                             +
         'source', 'finance_sku_order_details_fast_mtd'\r                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     );\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   if v_detail_mode then\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     return (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       with order_base as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         select *\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             o.marketplace_order_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             o.tenant_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             o.marketplace_account_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             o.order_created_at,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             timezone('Asia/Jakarta', o.order_created_at)::date as order_date,\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
             coalesce(nullif(o.order_id::text, ''), nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), o.marketplace_order_id::text) as order_key,\r                                                                                                                                                                                                                                                                                                                               +
             coalesce(nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), nullif(o.order_id::text, '')) as order_sn,\r                                                                                                                                                                                                                                                                                                                                                              +
             coalesce(nullif(o.tracking_number, ''), nullif(o.label_code, ''), nullif(o.package_id, '')) as tracking_number,\r                                                                                                                                                                                                                                                                                                                                                                       +
             lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) as status_text,\r                                                                                                                                                                                                                                                                                                                                                         +
             coalesce(nullif(o.gross_amount, 0), nullif(o.total_amount, 0), nullif(o.paid_amount, 0), 0)::numeric as order_gross,\r                                                                                                                                                                                                                                                                                                                                                                  +
             case\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
               when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'\r                                                                                                                                                                                                                                                                                                                                                                        +
               when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'\r                                                                                                                                                                                                                                                                                                                                                                        +
               else lower(regexp_replace(coalesce(o.marketplace, 'unknown'), '[^a-z0-9]+', '', 'g'))\r                                                                                                                                                                                                                                                                                                                                                                                               +
             end as marketplace_group\r                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           from public.marketplace_orders o\r                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           where coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) >= v_start_ts\r                                                                                                                                                                                                                                                                                                                                                                                               +
       and coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) < v_end_ts\r                                                                                                                                                                                                                                                                                                                                                                                                        +
             and (v_role = 'service_role' or o.tenant_id = v_tenant_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                            +
             and (v_account_id is null or o.marketplace_account_id = v_account_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
         ) o\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         where (v_marketplace is null or v_marketplace = '' or o.marketplace_group = public._finance_marketplace_norm_20260624(v_marketplace))\r                                                                                                                                                                                                                                                                                                                                                     +
           and o.status_text not like '%cancel%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%batal%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           and o.status_text not like '%unpaid%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%in_cancel%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           and o.status_text not like '%refund%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           and o.status_text not like '%return%'\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       finance_by_order as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ob.marketplace_order_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)), 0)::numeric as payout,\r                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.gross_amount, fr.gross_sales, 0)), 0)::numeric as finance_gross,\r                                                                                                                                                                                                                                                                                                                                                                                               +
           coalesce(sum(coalesce(fr.platform_fee, 0)), 0)::numeric as platform_fee,\r                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.commission_fee, 0)), 0)::numeric as commission_fee,\r                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(sum(coalesce(fr.affiliate_fee, 0)), 0)::numeric as affiliate_fee,\r                                                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.shipping_fee, 0)), 0)::numeric as shipping_fee,\r                                                                                                                                                                                                                                                                                                                                                                                                                +
           coalesce(sum(coalesce(fr.discount_amount, 0)), 0)::numeric as discount_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                          +
           coalesce(sum(coalesce(fr.voucher_amount, 0)), 0)::numeric as voucher_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                            +
           coalesce(sum(coalesce(fr.refund_amount, 0)), 0)::numeric as refund_amount,\r                                                                                                                                                                                                                                                                                                                                                                                                              +
           coalesce(sum(coalesce(fr.adjustment_amount, 0)), 0)::numeric as adjustment_amount\r                                                                                                                                                                                                                                                                                                                                                                                                       +
         from order_base ob\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         join \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           select tenant_id, marketplace_account_id, marketplace, order_id, marketplace_order_id, gross_amount, gross_sales, payout_amount, received_amount, net_settlement, platform_fee, commission_fee, affiliate_fee, shipping_fee, discount_amount, voucher_amount, refund_amount, adjustment_amount\r                                                                                                                                                                                          +
           from public.marketplace_finance_reports\r                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           where lower(coalesce(marketplace, '')) not in ('tiktok', 'tiktok_shop')\r                                                                                                                                                                                                                                                                                                                                                                                                                 +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           union all\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           select tenant_id, marketplace_account_id, marketplace, coalesce(nullif(order_id, ''), nullif(order_sn, ''), nullif(external_order_id, '')) as order_id, marketplace_order_id, gross_amount, gross_amount as gross_sales, received_amount as payout_amount, received_amount, net_settlement, null as platform_fee, null as commission_fee, null as affiliate_fee, null as shipping_fee, null as discount_amount, null as voucher_amount, null as refund_amount, null as adjustment_amount\r+
           from public.marketplace_finance_items\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           where lower(coalesce(marketplace, '')) in ('tiktok', 'tiktok_shop')\r                                                                                                                                                                                                                                                                                                                                                                                                                     +
         ) fr\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           on fr.tenant_id = ob.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and fr.marketplace_account_id = ob.marketplace_account_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
          and fr.order_id = ob.order_key\r                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         group by ob.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       line_base as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ob.*,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           oi.marketplace_order_item_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           coalesce(nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku_id,\r                                                                                                                                                                                                                                                                                                                                                                                        +
           coalesce(nullif(oi.marketplace_sku, ''), nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku,\r                                                                                                                                                                                                                                                                                                                                                           +
           coalesce(nullif(oi.marketplace_seller_sku, ''), nullif(oi.seller_sku, '')) as marketplace_seller_sku,\r                                                                                                                                                                                                                                                                                                                                                                                   +
           coalesce(nullif(oi.local_sku, ''), nullif(oi.mapped_local_sku, '')) as local_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                       +
           coalesce(nullif(oi.marketplace_product_name, ''), nullif(oi.product_name, ''), nullif(oi.local_product_name, '')) as product_name,\r                                                                                                                                                                                                                                                                                                                                                      +
           coalesce(nullif(oi.marketplace_variant_name, ''), nullif(oi.variant_name, ''), nullif(oi.variation_name, '')) as variant_name,\r                                                                                                                                                                                                                                                                                                                                                          +
           greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1)::numeric as qty,\r                                                                                                                                                                                                                                                                                                                                                                                                    +
           coalesce(\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             nullif(oi.gross_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             nullif(oi.paid_amount, 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             nullif(oi.unit_gross_amount, 0) * greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1),\r                                                                                                                                                                                                                                                                                                                                                                                +
             0\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           )::numeric as line_gross\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         from order_base ob\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         join public.marketplace_order_items oi\r                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           on oi.tenant_id = ob.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and oi.marketplace_order_id = ob.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         where (v_marketplace_sku is null or v_marketplace_sku in (\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
             lower(coalesce(oi.marketplace_sku_id, '')),\r                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             lower(coalesce(oi.marketplace_sku, '')),\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
             lower(coalesce(oi.remote_sku_id, '')),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             lower(coalesce(oi.marketplace_seller_sku, '')),\r                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             lower(coalesce(oi.seller_sku, ''))\r                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           ))\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           and (v_local_sku is null or v_local_sku = lower(coalesce(oi.local_sku, oi.mapped_local_sku, '')))\r                                                                                                                                                                                                                                                                                                                                                                                       +
           and (v_search is null or lower(concat_ws(' ', ob.order_key, ob.order_sn, ob.tracking_number, oi.marketplace_sku_id, oi.marketplace_sku, oi.marketplace_seller_sku, oi.seller_sku, oi.local_sku, oi.mapped_local_sku, oi.marketplace_product_name, oi.product_name, oi.marketplace_variant_name, oi.variant_name)) like '%' || v_search || '%')\r                                                                                                                                          +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       line_calc as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select lb.*, sum(lb.line_gross) over (partition by lb.marketplace_order_id) as order_line_gross\r                                                                                                                                                                                                                                                                                                                                                                                           +
         from line_base lb\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       enriched_base as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           lc.*,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           coalesce(f.payout, 0)::numeric as order_payout,\r                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           (coalesce(f.payout, 0) <> 0) as has_payout\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         from line_calc lc\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         left join finance_by_order f on f.marketplace_order_id = lc.marketplace_order_id\r                                                                                                                                                                                                                                                                                                                                                                                                          +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       filtered as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
         select *\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from enriched_base\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         where (v_filter = 'all' or (v_filter = 'paid' and has_payout) or (v_filter = 'unpaid' and not has_payout))\r                                                                                                                                                                                                                                                                                                                                                                                +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       counted as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         select filtered.*, count(*) over ()::integer as total_count\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
         from filtered\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         select *\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         from counted\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         order by order_created_at desc, order_key\r                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         offset v_offset\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         limit v_page_size\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_sku as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         select tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, '')) as marketplace_sku_id,\r                                                                                                                                                                                                                                                                                                                                                                                    +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\r                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(marketplace_sku_id, '') is not null\r                                                                                                                                                                                                                                                                                                                                                                                                    +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, ''))\r                                                                                                                                                                                                                                                                                                                                                                                                         +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_seller as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         select tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, '')) as marketplace_seller_sku,\r                                                                                                                                                                                                                                                                                                                                                                            +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\r                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(marketplace_seller_sku, '') is not null\r                                                                                                                                                                                                                                                                                                                                                                                                +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, ''))\r                                                                                                                                                                                                                                                                                                                                                                                                     +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       hpp_local as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         select tenant_id, marketplace_account_id, lower(nullif(local_sku, '')) as local_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                      +
                max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
                max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\r                                                                                                                                                                                                                                                                                                                                                                                                   +
         from public.marketplace_variant_hpp_mappings\r                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         where coalesce(is_active, true) is true and nullif(local_sku, '') is not null\r                                                                                                                                                                                                                                                                                                                                                                                                             +
           and (v_role = 'service_role' or tenant_id = v_tenant_id)\r                                                                                                                                                                                                                                                                                                                                                                                                                                +
         group by tenant_id, marketplace_account_id, lower(nullif(local_sku, ''))\r                                                                                                                                                                                                                                                                                                                                                                                                                  +
       ),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       paged_enriched as (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         select\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           p.*,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           coalesce(hs.hpp, hsel.hpp, hl.hpp, 0)::numeric as unit_hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                             +
           coalesce(hs.target_margin, hsel.target_margin, hl.target_margin, 0)::numeric as target_margin\r                                                                                                                                                                                                                                                                                                                                                                                           +
         from paged p\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         left join public.marketplace_variant_hpp_mappings hpp\r                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           on hpp.tenant_id = p.tenant_id\r                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
          and (\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
            (p.marketplace_group = 'shopee' and hpp.marketplace = 'shopee')\r                                                                                                                                                                                                                                                                                                                                                                                                                        +
            or (p.marketplace_group = 'tiktok_shop' and hpp.marketplace = 'tiktok_shop')\r                                                                                                                                                                                                                                                                                                                                                                                                           +
          )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
          and coalesce(nullif(p.marketplace_sku_id, ''), p.marketplace_product_id) = coalesce(nullif(hpp.marketplace_variant_id, ''), hpp.marketplace_product_id)\r                                                                                                                                                                                                                                                                                                                                  +
       )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       select jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
         'rows', coalesce(jsonb_agg(jsonb_build_object(\r                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'source', 'finance_sku_order_details_fast_mtd_detail',\r                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_id', order_key,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'order_sn', order_sn,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'marketplace_order_id', marketplace_order_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'marketplace_order_item_id', marketplace_order_item_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'resi', tracking_number,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           'tracking_number', tracking_number,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'order_date', order_created_at,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           'order_created_at', order_created_at,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'marketplace', marketplace_group,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'marketplace_account_id', marketplace_account_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'local_sku', coalesce(nullif(local_sku, ''), '-'),\r                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           'sku', coalesce(nullif(local_sku, ''), nullif(marketplace_sku_id, ''), nullif(marketplace_seller_sku, ''), '-'),\r                                                                                                                                                                                                                                                                                                                                                                        +
           'marketplace_sku_id', marketplace_sku_id,\r                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'marketplace_sku', marketplace_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'marketplace_seller_sku', marketplace_seller_sku,\r                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           'product_name', product_name,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'variant_name', variant_name,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           'marketplace_variation_name', variant_name,\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'qty', qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'quantity', qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           'gross', line_gross,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           'gross_amount', line_gross,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           'gross_total', line_gross,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           'gross_per_item', case when qty > 0 then line_gross / qty else 0 end,\r                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'payout', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,\r                                                                                                                                                                                                                                                                                                                                                                 +
           'payout_amount', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,\r                                                                                                                                                                                                                                                                                                                                                          +
           'payout_per_item', case when has_payout and order_line_gross > 0 and qty > 0 then (order_payout * (line_gross / order_line_gross)) / qty else 0 end,\r                                                                                                                                                                                                                                                                                                                                    +
           'hpp', unit_hpp * qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           'hpp_total', unit_hpp * qty,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
           'hpp_per_item', unit_hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           'unit_hpp', unit_hpp,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
           'hpp_status', case when unit_hpp > 0 then 'HPP mapping' else 'HPP belum mapping' end,\r                                                                                                                                                                                                                                                                                                                                                                                                   +
           'target_margin_percent', target_margin,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           'finance_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end,\r                                                                                                                                                                                                                                                                                                                                                                                                        +
           'payout_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end\r                                                                                                                                                                                                                                                                                                                                                                                                          +
         ) order by order_created_at desc, order_key), '[]'::jsonb),\r                                                                                                                                                                                                                                                                                                                                                                                                                               +
         'page', v_page,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         'page_size', v_page_size,\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         'total', coalesce(max(total_count), 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         'total_count', coalesce(max(total_count), 0),\r                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         'total_pages', greatest(1, ceil(coalesce(max(total_count), 0)::numeric / v_page_size)::integer),\r                                                                                                                                                                                                                                                                                                                                                                                          +
         'source', 'finance_sku_order_details_fast_mtd'\r                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       )\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       from paged_enriched\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     );\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   end if;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 \r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   return jsonb_build_object('ok', true);\r                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 end;\r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
